// Personal library, forgiving search, and provider-supported resume integration.
const Core=RadhaCore;
if(!history||typeof history!=='object'||Array.isArray(history))history={};
for(const id of Object.keys(history))if(!history[id]||typeof history[id]!=='object')delete history[id];
let recommended=[],recRequest=0,exactSearch=false;
const originalRender=render,originalLoad=load,originalPlay=play;
function knownTitles(){return [...films,...saved,...recommended,...Object.values(history).map(h=>h.film).filter(Boolean)];}
function personalCard(f,resume=false){const h=history[f.id],percent=h?.duration?Math.min(100,100*h.time/h.duration):0;return `<article class="card"><div class="poster">${f.image?`<img src="${esc(f.image)}" alt="${esc(f.title)}" loading="lazy">`:''}<button class="play" data-personal="${esc(f.id)}" aria-label="${resume?'Resume':'Watch'} ${esc(f.title)}"><span class="postertitle">${esc(f.title)}</span></button>${resume?`<span class="resume">${f.type==='series'?`S${h.season} E${h.episode} · `:''}${Math.floor(h.time/60)} min watched</span><div class="progressbar" style="width:${percent}%"></div>`:''}</div><h3>${esc(f.title)}</h3><p class="cardmeta">${esc(f.reason||f.year||'')}</p>${resume?`<button class="textbutton" data-remove="${esc(f.id)}">Remove from watching</button>`:''}</article>`;}
function renderPersonal(){const rows=Object.values(history).filter(h=>h?.film&&h.time>=5&&!h.completed).sort((a,b)=>(b.updated||0)-(a.updated||0));$('#watchingGrid').innerHTML=rows.map(h=>personalCard(h.film,true)).join('');$('#watchingEmpty').hidden=rows.length>0;$('#recommendGrid').innerHTML=recommended.map(f=>personalCard(f)).join('');$('#recommendSection').hidden=!recommended.length;}
render=function(){for(const f of [...films,...saved])if(history[f.id]&&!history[f.id].film)history[f.id].film=f;originalRender();renderPersonal();};
load=async function(append=false){const input=$('#search'),original=input.value;const query=exactSearch?original:Core.correct(original,knownTitles().map(f=>f.title));$('#correction').hidden=original===query;$('#correctionText').textContent=`Showing results for “${query}”. `;input.value=query;const pending=originalLoad(append);input.value=original;await pending;};
$('#search').oninput=()=>{exactSearch=false;clearTimeout(debounce);debounce=setTimeout(()=>load(),400);};$('#searchOriginal').onclick=()=>{exactSearch=true;load();};
play=function(id){const f=knownTitles().find(f=>f.id===id);if(!f)return;if(!films.some(x=>x.id===id)&&!saved.some(x=>x.id===id))films.push(f);originalPlay(id);$('#playbackStatus').textContent='Waiting for playback progress…';};
frame=function(start){if(!active)return;const season=Math.max(1,parseInt($('#season').value)||1),episode=Math.max(1,parseInt($('#episode').value)||1);$('#season').value=season;$('#episode').value=episode;const path=active.type==='series'?`tv/${active.tmdb}/${season}/${episode}`:`movie/${active.tmdb}`,p=new URLSearchParams({color:'ED1935',episodeSelector:'true',nextEpisode:'true',autoplayNextEpisode:String($('#autonext').checked)}),pos=history[active.id];if(Number.isFinite(start))p.set('progress',String(start));else if(pos&&!pos.completed&&pos.season===season&&pos.episode===episode)p.set('progress',String(pos.time));const iframe=document.createElement('iframe');iframe.src='https://vidy.st/'+path+'?'+p;iframe.title=active.title+' video player';iframe.allow='encrypted-media; autoplay *; fullscreen *; picture-in-picture';iframe.allowFullscreen=true;iframe.referrerPolicy='strict-origin-when-cross-origin';$('#embedBox').replaceChildren(iframe);};
$('#loadEpisode').onclick=()=>frame();
async function refreshRecommendations(){const rid=++recRequest,seeds=Object.values(history).filter(h=>h?.film&&h.time>=60).sort((a,b)=>(b.updated||0)-(a.updated||0)).slice(0,3);if(!seeds.length){recommended=[];renderPersonal();return;}const responses=await Promise.allSettled(seeds.map(async h=>{const r=await fetch('/.netlify/functions/recommendations?'+new URLSearchParams({type:h.film.type==='series'?'tv':'movie',id:h.film.tmdb}));if(!r.ok)return [];return (await r.json()).results.map(f=>({...f,reason:'Because you watched '+h.film.title}));}));if(rid!==recRequest)return;const seen=new Set(Object.keys(history));recommended=[];for(let i=0;i<6;i++)for(const r of responses){const f=r.status==='fulfilled'?r.value[i]:null;if(f&&!seen.has(f.id)){seen.add(f.id);recommended.push(f);}}renderPersonal();}
document.addEventListener('click',e=>{const p=e.target.closest('[data-personal]'),r=e.target.closest('[data-remove]');if(p)play(p.dataset.personal);if(r){delete history[r.dataset.remove];persist();renderPersonal();refreshRecommendations();}});
// Capture first, to replace the older handler without letting it overwrite richer progress.
window.addEventListener('message',e=>{const f=$('#embedBox iframe');if(!active||!f||e.source!==f.contentWindow||!['https://vidy.st','https://www.vidy.st'].includes(e.origin))return;const d=Core.eventData(e.data);if(!d)return;e.stopImmediatePropagation();const h=Core.progress(history[active.id],active,d,Number($('#season').value),Number($('#episode').value));history[active.id]=h;$('#season').value=h.season;$('#episode').value=h.episode;$('#playbackStatus').textContent=`Saved at ${Math.floor(h.time/60)}:${String(h.time%60).padStart(2,'0')}${active.type==='series'?` · S${h.season} E${h.episode}`:''}`;persist();},true);
$('#player').onclose=()=>{$('#embedBox').replaceChildren();active=null;persist();renderPersonal();refreshRecommendations();};
try{$('#autonext').checked=JSON.parse(localStorage.getItem('radha-autonext')||'true');}catch{}
$('#autonext').onchange=()=>{try{localStorage.setItem('radha-autonext',JSON.stringify($('#autonext').checked));}catch{}frame();};
$('#skipIntro').onclick=()=>{const h=history[active?.id];if(!h||Date.now()-h.updated>20000){$('#playbackStatus').textContent='Wait for playback progress before skipping.';return;}frame(Math.min(h.time+Number($('#introSeconds').value),h.duration||Infinity));$('#playbackStatus').textContent='Skipping your chosen duration; the external player reloads.';};
$('#clearHistory').onclick=()=>$('#historyDialog').showModal();$('#confirmClear').onclick=()=>{history={};recommended=[];persist();renderPersonal();$('#historyDialog').close();refreshRecommendations();};
window.addEventListener('pagehide',persist);renderPersonal();refreshRecommendations();
let nativePlayer=null;
window.addEventListener('message',e=>{const f=$('#embedBox iframe');if(!f||e.source!==f.contentWindow||!['https://vidy.st','https://www.vidy.st'].includes(e.origin))return;if(e.data?.type==='RADHA_PLAYER_READY')nativePlayer=e.source;if(e.data?.type==='RADHA_SEEK_RESULT')$('#playbackStatus').textContent=e.data.ok?'Seek complete · fullscreen preserved':'Video is not ready to seek yet.';});
window.radhaSeek=function(seconds){const f=$('#embedBox iframe');if(!f||!Number.isFinite(seconds)||Math.abs(seconds)>120)return false;if(nativePlayer===f.contentWindow){f.contentWindow.postMessage({type:'RADHA_PLAYER_SEEK',seconds},new URL(f.src).origin);return true;}f.contentWindow.postMessage({type:'RADHA_PLAYER_PING'},new URL(f.src).origin);$('#playbackStatus').textContent='Use the player’s forward/back buttons. In the app, update Android System WebView if gestures are unavailable.';return false;};
$('#skipIntro').onclick=()=>window.radhaSeek(Number($('#introSeconds').value));
